MATCH (equipment:Equipment {tag: 'E-2-1'})-[:send_to]-(valve:PlantItem)<-[:control]-(actuator:ActuatingFunction)<-[:send_signal_to]-(controller:ProcessInstrumentationFunction)
RETURN DISTINCT controller.loop_tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: "T-2-1"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "E-2-1"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (source:PlantItem)-[:send_to*1..]->(:PlantItem {tag: "TK-2-6"})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
